SET NAMES utf8mb4;
CREATE TABLE usuarios (id int NOT NULL AUTO_INCREMENT PRIMARY KEY, usuario varchar(100) NOT NULL, email varchar(150) NOT NULL UNIQUE, password varchar(255) NOT NULL, moneda varchar(3) NOT NULL DEFAULT 'EUR', fecha_registro datetime DEFAULT NULL, fecha_actualizacion timestamp NULL DEFAULT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categorias (id int NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre varchar(100) NOT NULL, tipo_movimiento enum('Ingreso','Gasto') DEFAULT NULL, usuario_id int DEFAULT NULL, fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, fecha_actualizacion timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cuentas (id int NOT NULL AUTO_INCREMENT PRIMARY KEY, usuario_id int DEFAULT NULL, nombre varchar(100) DEFAULT NULL, tipo_cuenta varchar(50) DEFAULT NULL, saldo_inicial decimal(10,2) DEFAULT NULL, fecha_creacion timestamp NULL DEFAULT NULL, fecha_actualizacion timestamp NULL DEFAULT NULL, FOREIGN KEY (usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE movimientos (id int NOT NULL AUTO_INCREMENT PRIMARY KEY, usuario_id int NOT NULL, categoria_id int NOT NULL, cuenta_id int NOT NULL, cuenta_origen_id int DEFAULT NULL, cuenta_destino_id int DEFAULT NULL, tipo_movimiento enum('Ingreso','Gasto','Transferencia','') NOT NULL, tipo_registro enum('Fijo','Variable') NOT NULL, cantidad decimal(10,2) DEFAULT NULL, fecha_registro datetime DEFAULT NULL, comentario varchar(255) DEFAULT NULL, FOREIGN KEY (usuario_id) REFERENCES usuarios(id), FOREIGN KEY (categoria_id) REFERENCES categorias(id), FOREIGN KEY (cuenta_id) REFERENCES cuentas(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
